class FloatPrecisionCertificateTest {
 @org.junit.jupiter.api.io.TempDir Path folder;
 static DocumentSnapshot original()throws Exception{try(var stream=FloatPrecisionCertificateTest.class.getResourceAsStream("/regressions/p7-ind-01.json")){assertNotNull(stream);return new ProjectCodec().decode(stream.readAllBytes());}}
 static DocumentSnapshot original02()throws Exception{try(var in=FloatPrecisionCertificateTest.class.getResourceAsStream("/regressions/p7-ind-02.json")){assertNotNull(in);return new ProjectCodec().decode(in.readAllBytes());}}
 static DocumentSnapshot safe()throws Exception{var d=original();d=ModelEdits.editBone(d,id(1),b->b.withLocal(Transform.IDENTITY));d=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(20,60,0,1,1)));return d.withConstraints(List.of(((IkConstraint)d.constraints().get(0)).withSoftness(10).withOptions(true,false,true,false)));}
 static DocumentSnapshot safeZero()throws Exception{var d=safe();return d.withConstraints(List.of(((IkConstraint)d.constraints().get(0)).withSoftness(0).withOptions(true,false,false,false)));}
 static DocumentSnapshot line(DocumentSnapshot d,double x,double y,double dx,double dy){d=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(x,y,0,1,1)));var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));return AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(dx,dy));}
 static String refuses(DocumentSnapshot d)throws Exception{var codec=new ProjectCodec();assertEquals(d,codec.decode(codec.encode(d)));var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(d));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());return error.getMessage();}

 @Test void actualIndependentAcceptedCounterexampleNowRefusesWithoutChangingDoubleProject()throws Exception{var d=original();var codec=new ProjectCodec();assertEquals(d,codec.decode(codec.encode(d)));var pose=d.evaluateWorld();var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(d));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertTrue(error.getMessage().contains("tipX")||error.getMessage().contains("originX"),error.getMessage());assertEquals(pose,d.evaluateWorld());}
 @Test void bothBendsOfOriginalRootAreRejectedByActualEndpointError()throws Exception{var d=original();for(boolean bend:new boolean[]{false,true}){var ik=((IkConstraint)d.constraints().get(0)).withOptions(bend,false,true,false);var candidate=d.withConstraints(List.of(ik));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("float-precision"));}}
 @Test void exactlyRepresentableSaturationAndSafeInteriorRemainAvailable()throws Exception{var d=safe();assertDoesNotThrow(()->RuntimeRange.validate(d));var axis=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(460,-20,0,1,1)));assertDoesNotThrow(()->RuntimeRange.validate(axis));}
 @Test void aLongDescendantEndpointCannotHideBehindPassingLinearMatrices()throws Exception{var d=safe();var world=d.evaluateWorld().bones().get(id(3));double length=1e7,desired=Math.acos(-world.origin().x()/length),rotation=Math.toDegrees(desired-Math.atan2(world.matrix().c(),world.matrix().a()));var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(99),"amplified descendant",id(3),new Transform(0,0,rotation,1,1),length));var candidate=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());assertTrue(Math.abs(candidate.evaluateWorld().bones().get(id(99)).tip().x())<1e-6);var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("amplified descendant.tipX"),e.getMessage());assertEquals(candidate,new ProjectCodec().decode(new ProjectCodec().encode(candidate)));}
 @Test void fullTargetHullCrossingSoftSaturationIsRefusedBeforeAnySparseTimeSampling()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(200.,0.));var candidate=d;var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("float-precision"));assertTrue(e.getMessage().contains("hull")||e.getMessage().contains("budget"),e.getMessage());}
 @Test void boundedInteriorLinearTargetMotionKeepsAWholeRangeProof()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(5.,-5.));var candidate=d;assertDoesNotThrow(()->RuntimeRange.validate(candidate));}
 @Test void neutralKeysDoNotInventDynamicSoftnessInputs()throws Exception{var d=ModelEdits.editBone(safe(),id(4),b->b.withLocal(new Transform(460,-20,0,1,1)));d=AnimationEdits.put(d,d.animations().get(0).id(),id(4),Channel.TRANSLATE,0,List.of(0.,0.));var candidate=d;assertDoesNotThrow(()->RuntimeRange.validate(candidate));}
 @Test void squareRootErrorEnclosesPositiveDisplacementAtZeroAndAcrossItsFullRange(){var input=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(0,10000),.01);var proof=input.sqrt();assertTrue(proof.e()>=.1);for(double value:new double[]{0,1e-12,1e-6,.001,1,100,10000})for(double delta:new double[]{0,.005,.009}){float actual=(float)Math.sqrt((float)(value+delta));assertTrue(Math.abs(actual-Math.sqrt(value))<=proof.e());}}
 @Test void divisionErrorEnclosesActualFloatResultsAndRejectsPossibleZeroDenominator(){var numerator=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(-10,20),.001);var denominator=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(.1,2),.0001);var proof=numerator.div(denominator);for(double a:new double[]{-10,-1,0,20})for(double b:new double[]{.1,.5,2}){float actual=(float)(a+.0005)/(float)(b-.00005);assertTrue(Math.abs(actual-a/b)<=proof.e());}assertThrows(RuntimeException.class,()->numerator.div(new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(0,.1),.001)));}
 @Test void animatedParentSignedPiBranchCannotBeHiddenByAnInteriorCosineRange()throws Exception{var d=ModelEdits.editBone(safe(),id(4),b->b.withLocal(new Transform(-130,20,0,1,1)));var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(0.,-80.));var candidate=d;var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("atan2"),e.getMessage());}
 @Test void unrelatedTrackCannotSilentlyChangeTheFloatLoopPeriod()throws Exception{var d=safe();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(88),"unrelated",id(1),Transform.IDENTITY,0));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(5.,-5.));d=AnimationEdits.put(d,clip,id(88),Channel.TRANSLATE,1.1,List.of(1.,0.));var candidate=d;assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("loop period"));}
 @Test void unprovedBezierTargetIsPreciseAndLossless()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(10.,0.));d=AnimationEdits.curves(d,clip,Set.of(d.animation(clip).timelines().get(0).keys().get(0).id()),List.of(new Curve(Curve.Kind.BEZIER,.2,40,.8,-40),Curve.LINEAR));var candidate=d;assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("Bezier target"));}
 @Test void descendantOnlyAnimationMustCertifyItsEndpointAmplification()throws Exception{var d=safe();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(77),"animated descendant",id(3),Transform.IDENTITY,1));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());RuntimeRange.validate(d);d=AnimationEdits.put(d,d.animations().get(0).id(),id(77),Channel.SCALE,1,List.of(1e7,1e7));var candidate=d;var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));}
 @Test void steppedActivationFromZeroMixSetupCannotBypassTheOriginalCounterexample()throws Exception{var d=original();var ik=(IkConstraint)d.constraints().get(0);var values=ConstraintChannel.IK.values(ik);d=d.withConstraints(List.of(ik.withMix(0)));var old=d.animations().get(0);var key=new Keyframe(id(76),0,values,Collections.nCopies(5,Curve.STEPPED));var clip=new AnimationClip(old.id(),old.name(),old.timelines(),old.deforms(),List.of(new ConstraintTimeline(ik.id(),ConstraintChannel.IK,List.of(key))));d=new DocumentSnapshot(d.bones(),d.slots(),d.attachments(),List.of(clip),d.constraints());var candidate=d;var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));}

 @Test void exactSecondIndependentNoRasterProjectIsLosslessButCannotPublish()throws Exception{var d=original02();var pose=d.evaluateWorld();assertTrue(refuses(d).contains("hull"));assertEquals(pose,d.evaluateWorld());}
 @Test void zeroSoftnessLinearCrossingBothCircleBoundariesCoversMirrorsAndBothBends()throws Exception{for(double sx:new double[]{-1,1})for(double sy:new double[]{-1,1})for(boolean bend:new boolean[]{false,true})for(double radius:new double[]{70,130}){var d=safeZero();d=ModelEdits.editBone(d,id(1),b->b.withLocal(new Transform(0,0,0,sx,sy)));d=d.withConstraints(List.of(((IkConstraint)d.constraints().get(0)).withOptions(bend,false,false,false)));refuses(line(d,-40+radius-.02,-20,.04,0));}}
 @Test void safeZeroSoftnessInteriorMotionAndStableOuterClampRemainAvailable()throws Exception{var inside=line(safeZero(),20,60,5,-5);assertDoesNotThrow(()->RuntimeRange.validate(inside));var outside=line(safeZero(),460,-20,5,0);assertDoesNotThrow(()->RuntimeRange.validate(outside));}
 @Test void zeroSoftnessChangingCausalRotationCannotBypassTheFullHullProof()throws Exception{var d=safeZero();d=AnimationEdits.put(d,d.animations().get(0).id(),id(1),Channel.ROTATE,1,List.of(1.));assertTrue(refuses(d).contains("causal"));}
 @Test void zeroSoftnessDescendantOnlyMotionCannotBypassEndpointAmplification()throws Exception{var d=safeZero();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(77),"moving lever",id(3),Transform.IDENTITY,1));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());RuntimeRange.validate(d);d=AnimationEdits.put(d,d.animations().get(0).id(),id(77),Channel.SCALE,1,List.of(1e7,1e7));refuses(d);}
 @Test void zeroSoftnessNonuniformEllipseAndFirstSegmentFallbackRefuseUnprovedMotion()throws Exception{var ellipse=ModelEdits.editBone(safeZero(),id(2),b->b.withLocal(new Transform(-40,-20,10,2,.8)));assertTrue(refuses(line(ellipse,20,60,5,-5)).contains("ellipse"));var fallback=ModelEdits.editBone(safeZero(),id(3),b->b.withLocal(new Transform(0,0,15,1,1)));assertTrue(refuses(line(fallback,20,60,5,-5)).contains("fallback"));}
 @Test void zeroMixSetupCannotHideAnUnsafeSteppedActivation()throws Exception{var d=original02();var ik=((IkConstraint)d.constraints().get(0)).withSoftness(0);d=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(90,-20,0,1,1)));d=d.withConstraints(List.of(ik.withMix(0)));var old=d.animations().get(0);var key=new Keyframe(id(76),1,ConstraintChannel.IK.values(ik),Collections.nCopies(5,Curve.STEPPED));d=d.withAnimations(List.of(new AnimationClip(old.id(),old.name(),List.of(),List.of(),List.of(new ConstraintTimeline(ik.id(),ConstraintChannel.IK,List.of(key))))));refuses(d);}

 static DocumentSnapshot constraintFixture(boolean local,boolean relative){
  var bones=List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"source",id(1),new Transform(-5,0,0,1,1),40),new Bone(id(3),"target",id(1),new Transform(10,5,15,1,1),20),new Bone(id(4),"descendant",id(2),new Transform(5,0,0,1,1),10));
  var slots=List.of(new Slot(id(10),"clip",id(1),id(20)),new Slot(id(11),"draw",id(4),id(21)));var attachments=List.<Attachment>of(new ClippingAttachment(id(20),"clip",id(10),List.of(new Vec2(-30,-30),new Vec2(30,-30),new Vec2(30,30),new Vec2(-30,30)),id(11)),new RegionAttachment(id(21),"region",id(11),"unused.png",Transform.IDENTITY,100,80));
  return new DocumentSnapshot(bones,slots,attachments).withConstraints(List.of(new TransformConstraint(id(30),"xy",0,true,List.of(id(2)),id(3),local,relative,List.of(0.,.5,.75,0.,0.,0.),List.of(0.,2.,-3.,0.,0.,0.))));
 }
 @ParameterizedTest @CsvSource({"false,false","false,true","true,false","true,true"}) void allFourTranslationModesProveAnimatedDescendantsAndWeightedDeform(boolean local,boolean relative)throws Exception{
  var d=constraintFixture(local,relative);var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(3),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(3),Channel.TRANSLATE,1,List.of(6.,-4.));d=MeshEdits.convert(d,id(21));d=WeightEdits.bind(d,id(21),List.of(new WeightEdits.Binding(id(2),.5),new WeightEdits.Binding(id(4),.5)));var values=new ArrayList<>(Collections.nCopies(MeshEdits.mesh(d,id(21)).deformSize(),0.));d=DeformEdits.put(d,clip,id(21),0,values);values.set(0,2.);d=DeformEdits.put(d,clip,id(21),1,values);var key=d.animation(clip).deforms().get(0).keys().get(0);d=AnimationEdits.curves(d,clip,Set.of(key.id()),List.of(new Curve(Curve.Kind.BEZIER,.2,-.1,.8,1.1)));var candidate=d;
  assertDoesNotThrow(()->RuntimeRange.validate(candidate));javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(100,80,java.awt.image.BufferedImage.TYPE_INT_ARGB),"PNG",folder.resolve("region.png").toFile());var codec=new SkeletonJsonCodec();var restored=codec.decode(codec.encode(d,Map.of(id(21),"region"),""),folder);assertEquals(1,restored.constraints().size());assertEquals(1,restored.animations().get(0).deforms().size());assertNotEquals(d.withConstraints(List.of()).evaluateWorld().bones().get(id(4)).matrix().tx(),d.evaluateWorld().bones().get(id(4)).matrix().tx());
 }
 @Test void solvedTranslationCannotHideOverflowBehindSafeUnconstrainedGeometry()throws Exception{
  var d=constraintFixture(false,false);d=ModelEdits.editBone(d,id(3),b->b.withLocal(new Transform(1e18,0,0,1,1)));var candidate=d;assertDoesNotThrow(()->ClipFloatCertificate.validate(candidate.withConstraints(List.of())));var e=assertThrows(ProjectFormatException.class,()->ClipFloatCertificate.validate(candidate));assertTrue(e.getMessage().contains("cross products"),e.getMessage());
 }
 @Test void angularOrMultipleActiveConstraintsRemainPreciseRefusals()throws Exception{
  var d=constraintFixture(false,false);var t=(TransformConstraint)d.constraints().get(0);var angular=d.withConstraints(List.of(t.withMix(0,1)));assertTrue(assertThrows(ProjectFormatException.class,()->ClipFloatCertificate.validate(angular)).getMessage().contains("translation-only"));var other=new TransformConstraint(id(31),"second",1,true,List.of(id(4)),id(3),true,false,t.mix(),t.offset());var multiple=d.withConstraints(List.of(t,other));assertTrue(assertThrows(ProjectFormatException.class,()->ClipFloatCertificate.validate(multiple)).getMessage().contains("one single-bone"));
 }
 @Test void disabledAngularConstraintDoesNotInventAnActiveWriter()throws Exception{var d=constraintFixture(false,false);var t=(TransformConstraint)d.constraints().get(0);var disabled=d.withConstraints(List.of(t.withMix(0,1).withEnabled(false)));assertDoesNotThrow(()->RuntimeRange.validate(disabled));}

 /** Golden observations come from an independently generated fixture, not another copy of the proof. */
 @Test void actualRuntimeRegionOffsetsStayInsideLocalProofBoxesIncludingLargeAngles()throws Exception{
  var resource=getClass().getResourceAsStream("/regressions/p6-region-boxes.json");assertNotNull(resource);var data=new ObjectMapper().readTree(resource);int count=0;
  for(var row:data.path("golden")){var t=row.path("transform");var r=new RegionAttachment(EntityId.create(),"region",EntityId.create(),"not-loaded.png",new Transform(t.path("x").asDouble(),t.path("y").asDouble(),t.path("rotation").asDouble(),t.path("scaleX").asDouble(),t.path("scaleY").asDouble()),row.path("width").asDouble(),row.path("height").asDouble());var boxes=ClipFloatCertificate.regionQuad(r);for(int i=0;i<8;i++){double value=(float)row.path("actualOffsets").get(i).asDouble();var interval=i%2==0?boxes.get(i/2).x():boxes.get(i/2).y();assertTrue(value>=interval.lo()&&value<=interval.hi(),"rotation="+r.local().rotation()+" component="+i+" actual="+value+" interval="+interval);count++;}}
  assertEquals(96,count);
 }
}
